"""Finite-dtau oracle for the negative-sign triangle fixture (oracle.txt).

Three sites, every off-diagonal hopping element -1, U=4, mu=2, dtau=0.5,
Ltr=4: 4096 Hubbard-Stratonovich configurations, 48 of them with a negative
weight. Uses NumPy only; nothing from the solver is imported.

HS side: B_sigma(l) = exp(-dtau K) diag(exp(sigma lambda s_l - dtau U/2)),
K = t - mu I, cosh(lambda) = exp(dtau U / 2), W = det(1 + B(L-1)...B(0))
for both spins. Z_HS and Z_abs include the HS normalisation 2^(-n Ltr).
Observables use the configuration Green functions G = (1 + A)^(-1) and
<c_i^dagger c_j> = delta_ij - G_ji.

Fock side: Tr[(exp(-dtau K_gc) exp(-dtau V))^Ltr] with Jordan-Wigner
operators; it must equal Z_HS. The continuous-time Z_ED is recorded only to
show that it differs at this dtau.

Configuration index c: bit k = l*n + i of c is 1 when s(l, i) = +1.

usage: python3 generate_oracle.py > oracle.txt
"""
import itertools
import sys

import numpy as np

N_SITE, LTR, U, MU, DTAU = 3, 4, 4.0, 2.0, 0.5


def expm_sym(a):
    w, v = np.linalg.eigh(a)
    return (v * np.exp(w)) @ v.T


def hs_side(t):
    n = N_SITE
    ncfg = 1 << (n * LTR)
    bits = (np.arange(ncfg)[:, None] >> np.arange(n * LTR)) & 1
    s = (2 * bits - 1).reshape(ncfg, LTR, n)
    expk = expm_sym(-DTAU * (t - MU * np.eye(n)))
    lam = np.arccosh(np.exp(DTAU * U / 2))
    w = np.ones(ncfg)
    dens = []
    for sigma in (1.0, -1.0):
        a = np.broadcast_to(np.eye(n), (ncfg, n, n)).copy()
        for l in range(LTR):
            b = expk[None, :, :] * np.exp(sigma * lam * s[:, l, :] - DTAU * U / 2)[:, None, :]
            a = b @ a
        m = np.eye(n) + a
        w *= np.linalg.det(m)
        dens.append(np.eye(n) - np.linalg.inv(m).swapaxes(-1, -2))
    n_up = np.diagonal(dens[0], axis1=1, axis2=2)
    n_dn = np.diagonal(dens[1], axis1=1, axis2=2)
    kinetic = sum(np.einsum('ij,kij->k', t, d) for d in dens)
    double = (n_up * n_dn).sum(axis=1)
    energy = kinetic + U * double
    ntot = (n_up + n_dn).sum(axis=1)
    norm = 2.0 ** (-n * LTR)
    return dict(w=w, s=s, Z_HS=w.sum() * norm, Z_abs=np.abs(w).sum() * norm,
                E=(w @ energy) / w.sum(), N=(w @ ntot) / w.sum(),
                D=(w @ double) / w.sum() / n)


def fock_side(t):
    n = N_SITE
    nmode = 2 * n
    dim = 1 << nmode
    eye2, z, low = np.eye(2), np.diag([1.0, -1.0]), np.array([[0.0, 1.0], [0.0, 0.0]])
    ops = []
    for k in range(nmode):  # Jordan-Wigner annihilators, mode k = spin * n + site
        mats = [z] * k + [low] + [eye2] * (nmode - k - 1)
        op = mats[0]
        for m in mats[1:]:
            op = np.kron(op, m)
        ops.append(op)
    num = [c.T @ c for c in ops]
    kin = sum(t[i, j] * ops[sp * n + i].T @ ops[sp * n + j]
              for sp in range(2) for i in range(n) for j in range(n) if i != j)
    ntot = sum(num)
    double = sum(num[i] @ num[n + i] for i in range(n))
    hub = kin + U * double
    kgc = kin - MU * ntot
    transfer = expm_sym(-DTAU * kgc) @ np.diag(np.exp(-DTAU * U * np.diag(double)))
    rho = np.linalg.matrix_power(transfer, LTR)
    z_t = np.trace(rho)
    z_ed = np.exp(-DTAU * LTR * np.linalg.eigvalsh(hub - MU * ntot)).sum()
    assert dim == hub.shape[0]
    return dict(Z=z_t, E=np.trace(hub @ rho) / z_t, N=np.trace(ntot @ rho) / z_t,
                D=np.trace(double @ rho) / z_t / n, Z_ED=z_ed)


def main():
    t = -np.ones((N_SITE, N_SITE))
    np.fill_diagonal(t, 0.0)
    hs = hs_side(t)
    fk = fock_side(t)
    neg = np.flatnonzero(hs['w'] < 0)
    for key in ('E', 'N', 'D'):
        assert abs(hs[key] - fk[key]) < 1e-10, key
    assert abs(hs['Z_HS'] - fk['Z']) < 1e-10 * fk['Z']
    out = sys.stdout
    out.write('# negative-sign triangle oracle; generated by generate_oracle.py (NumPy %s)\n'
              % np.__version__)
    out.write('# config index c: bit (l*n + i) set <=> s(l,i) = +1\n')
    for key, val in (('n', N_SITE), ('Ltr', LTR), ('U', U), ('mu', MU), ('dtau', DTAU),
                     ('configurations', 1 << (N_SITE * LTR)),
                     ('negative_configurations', len(neg))):
        out.write('%s %s\n' % (key, repr(val)))
    for key, val in (('Z_HS', hs['Z_HS']), ('Z_abs', hs['Z_abs']),
                     ('average_sign', hs['Z_HS'] / hs['Z_abs']),
                     ('E_hub', hs['E']), ('ntot', hs['N']), ('doublon', hs['D']),
                     ('Z_trotter', fk['Z']), ('E_trotter', fk['E']),
                     ('N_trotter', fk['N']), ('D_trotter', fk['D']),
                     ('Z_ED_continuous', fk['Z_ED'])):
        out.write('%s %.17g\n' % (key, val))
    out.write('negative_indices %s\n' % ' '.join(str(int(c)) for c in neg))
    out.write('first_negative_slice_major %s\n'
              % ' '.join(str(int(x)) for x in hs['s'][neg[0]].ravel()))


if __name__ == '__main__':
    main()
